(function(){
  let particles = [];
  let t = 0;
  const cx = () => W()/2, cy = () => H()/2;

  function hexAlpha(hex, a){
    let h = hex.replace('#','');
    if(h.length===3){ h = h.split('').map(c=>c+c).join(''); }
    const r=parseInt(h.substring(0,2),16);
    const g=parseInt(h.substring(2,4),16);
    const b=parseInt(h.substring(4,6),16);
    return `rgba(${r},${g},${b},${a})`;
  }

  function initParticles(){
    particles = [];
    const n = 110;
    for(let i=0;i<n;i++){
      const ang = Math.random()*Math.PI*2;
      const rad = Math.pow(Math.random(),0.5)*Math.max(W(),H())*0.62 + Math.min(W(),H())*0.16;
      const x = cx() + Math.cos(ang)*rad;
      const y = cy() + Math.sin(ang)*rad;
      particles.push({
        baseX:x, baseY:y,
        r: Math.random()*1.8+0.6,
        phase: Math.random()*Math.PI*2,
        speed: Math.random()*0.4+0.15,
        colorIdx: Math.floor(Math.random()*PALETTE.length)
      });
    }
  }
  initParticles();

  function drawVelvetFold(x0,y0,x1,y1,amp,freq,phase,color,alpha,width){
    ctx.beginPath();
    const steps=50;
    for(let i=0;i<=steps;i++){
      const p=i/steps;
      const x = x0+(x1-x0)*p;
      const y = y0+(y1-y0)*p + Math.sin(p*freq*Math.PI*2+phase)*amp*Math.sin(p*Math.PI);
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.strokeStyle = color;
    ctx.globalAlpha = alpha;
    ctx.lineWidth = width;
    ctx.lineCap='round';
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  function frame(){
    t += 0.007;
    const w = W(), h = H();
    ctx.clearRect(0,0,w,h);

    const g1 = ctx.createRadialGradient(w*0.08,h*0.06,0, w*0.08,h*0.06, Math.max(w,h)*0.5);
    g1.addColorStop(0, hexAlpha(PALETTE[1],0.15));
    g1.addColorStop(1, hexAlpha(PALETTE[1],0));
    ctx.fillStyle=g1;
    ctx.fillRect(0,0,w,h);

    const g2 = ctx.createRadialGradient(w*0.94,h*0.95,0, w*0.94,h*0.95, Math.max(w,h)*0.55);
    g2.addColorStop(0, hexAlpha(PALETTE[0],0.18));
    g2.addColorStop(1, hexAlpha(PALETTE[0],0));
    ctx.fillStyle=g2;
    ctx.fillRect(0,0,w,h);

    const foldCount = 7;
    for(let i=0;i<foldCount;i++){
      const p = i/(foldCount-1);
      const off = (p-0.5)*Math.min(w,h)*1.3;
      const x0 = -w*0.15 + off*0.3;
      const y0 = h*0.15 + off*0.9;
      const x1 = w*1.15 + off*0.3;
      const y1 = h*0.85 + off*0.9;
      const amp = 24 + Math.sin(t*0.4+i)*7;
      const freq = 2.2+i*0.15;
      const phase = t*0.6 + i*1.3;
      const colorHex = PALETTE[i%PALETTE.length];
      drawVelvetFold(x0,y0,x1,y1,amp,freq,phase, colorHex, 0.09+0.03*Math.sin(t+i), 3+(i%3));
    }

    for(const pt of particles){
      const dx = pt.baseX - cx(), dy = pt.baseY-cy();
      const dist = Math.hypot(dx,dy);
      const centerFade = Math.min(1, dist/(Math.min(w,h)*0.22));
      const twinkle = 0.35+0.65*Math.abs(Math.sin(t*pt.speed*3+pt.phase));
      const x = pt.baseX + Math.sin(t*pt.speed+pt.phase)*6;
      const y = pt.baseY + Math.cos(t*pt.speed*0.8+pt.phase)*6;
      const col = PALETTE[pt.colorIdx];
      ctx.beginPath();
      ctx.fillStyle = hexAlpha(col, 0.55*twinkle*centerFade);
      ctx.shadowColor = hexAlpha(col,0.5*centerFade);
      ctx.shadowBlur = 6;
      ctx.arc(x,y,pt.r,0,Math.PI*2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
